Fl_Slider *bt_exitline=(Fl_Slider *)0;

Fl_Window* make_exitwindow() {
  Fl_Window* w;
  { Fl_Window* o = win_exit = new Fl_Window(279, 100, "Post Office Shutdown");
    w = o;
    { Fl_Group* o = new Fl_Group(0, 0, 280, 100);
      pixmap_bg.label(o);
      o->align(FL_ALIGN_CENTER|FL_ALIGN_INSIDE);
      { Fl_Button* o = new Fl_Button(18, 10, 50, 50);
        o->box(FL_NO_BOX);
        pixmap_shredder2.label(o);
      }
      { Fl_Button* o = new Fl_Button(80, 15, 170, 40, "Taking \'special care\' of your mission critical mail data.");
        o->box(FL_BORDER_FRAME);
        o->color(0);
        o->labelsize(12);
        o->align(FL_ALIGN_WRAP);
      }
      { Fl_Slider* o = bt_exitline = new Fl_Slider(10, 69, 260, 21);
        o->type(3);
        o->box(FL_THIN_DOWN_BOX);
        o->color(53);
        o->selection_color(51);
        o->labelfont(1);
        o->labelsize(10);
        o->maximum(100);
        o->align(FL_ALIGN_CENTER|FL_ALIGN_INSIDE);
      }
      o->end();
    }
    o->set_modal();
    o->end();
  }
  return w;
}

